package com.shnewbs.deepprimal.core;

/** Bounded CPU frame intervals, including waits/limiting; never GPU execution time.
 * Context changes discard the crossing interval and all earlier samples.
 */
public final class FrameIntervalWindow {
  private final RollingTiming intervals, transitions;
  private long transitionCount;
  private Object world;
  private int width, height, fpsLimit, fullDistance, verticalDistance, lodDistance;
  private boolean focused, initialized;
  private long previous, generation;

  public FrameIntervalWindow(int capacity) {
    intervals = new RollingTiming(capacity);
    transitions = new RollingTiming(Math.min(capacity, 64));
  }

  /** Call on every observed frame, before publishing diagnostics. Returns true on a reset.
   * World uses identity so reconnects to the same dimension start a new window.
   */
  public synchronized boolean observe(long now, Object world, int width, int height,
      boolean focused, int fpsLimit, int fullDistance, int verticalDistance, int lodDistance) {
    boolean changed = !initialized || this.world != world || this.width != width
        || this.height != height || this.focused != focused || this.fpsLimit != fpsLimit
        || this.fullDistance != fullDistance || this.verticalDistance != verticalDistance
        || this.lodDistance != lodDistance || now - previous < 0;
    if (changed) {
      // Keep valid observed crossing gaps separate from steady-context percentiles.
      // This includes all intervening waits; it is not an isolated world-load timer.
      if (initialized && now - previous >= 0) {
        transitions.record(now - previous);
        transitionCount++;
      }
      intervals.reset();
      generation++;
      this.world = world;
      this.width = width;
      this.height = height;
      this.focused = focused;
      this.fpsLimit = fpsLimit;
      this.fullDistance = fullDistance;
      this.verticalDistance = verticalDistance;
      this.lodDistance = lodDistance;
      initialized = true;
    } else intervals.record(now - previous);
    previous = now;
    return changed;
  }

  public synchronized RollingTiming.Snapshot snapshot() { return intervals.snapshot(); }
  public synchronized RollingTiming.Snapshot transitionSnapshot() { return transitions.snapshot(); }
  public synchronized long transitionCount() { return transitionCount; }
  public synchronized long generation() { return generation; }

  /** Release the world reference and discard an observation gap, e.g. dashboard disabled. */
  public synchronized void clear() {
    intervals.reset();
    transitions.reset();
    transitionCount = 0;
    world = null;
    initialized = false;
  }
}

package com.shnewbs.deepprimal.client;

import com.mojang.blaze3d.systems.RenderSystem;
import com.shnewbs.deepprimal.client.render.HorizonRenderer;
import com.shnewbs.deepprimal.core.FrameIntervalWindow;
import com.shnewbs.deepprimal.diagnostics.LocalDashboard;
import com.shnewbs.deepprimal.settings.ClientPerformanceConfig;
import com.shnewbs.deepprimal.settings.RendererOwnership;
import com.shnewbs.deepprimal.settings.VisualPerformance;
import java.util.LinkedHashMap;
import net.minecraft.client.Minecraft;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.neoforge.client.event.RenderFrameEvent;

/** Frame interval includes frame limiting and waits; it is not GPU render time. */
public final class ClientTelemetry {
  private final FrameIntervalWindow frames = new FrameIntervalWindow(512);
  private long sampled, lastBuild, lastUpload, lastDraw, lastReceived, lastSync;

  @SubscribeEvent
  public void frame(RenderFrameEvent.Post event) {
    HorizonRenderer.INSTANCE.observeFrame(System.nanoTime());
    if (!LocalDashboard.running()) LocalDashboard.start();
    if (!LocalDashboard.running()) { frames.clear(); return; }
    long now = System.nanoTime();
    var mc = Minecraft.getInstance();
    boolean reset = frames.observe(now, mc.level, mc.getWindow().getWidth(),
        mc.getWindow().getHeight(), mc.isWindowActive(),
        mc.getFramerateLimitTracker().getFramerateLimit(),
        mc.options.getEffectiveRenderDistance(), ClientPerformanceConfig.VERTICAL_RENDER_DISTANCE.get(),
        com.shnewbs.deepprimal.settings.LodAccess.distance());
    if (!reset && now - sampled < 1_000_000_000L) return;
    sampled = now;
    var data = new LinkedHashMap<String, Object>();
    var stats = frames.snapshot();
    data.put("state", mc.level == null ? "Menu" : "In world");
    data.put("sampleTime", System.currentTimeMillis());
    data.put("frameMedianMs", stats.p50Nanos() / 1e6);
    data.put("frameP95Ms", stats.p95Nanos() / 1e6);
    data.put("frameP99Ms", stats.p99Nanos() / 1e6);
    data.put("frameSampleCount", stats.samples());
    var transitions = frames.transitionSnapshot();
    data.put("frameContextTransitionCount", frames.transitionCount());
    data.put("frameContextTransitionSamples", transitions.samples());
    data.put("frameContextTransitionP50Ms", transitions.p50Nanos() / 1e6);
    data.put("frameContextTransitionP95Ms", transitions.p95Nanos() / 1e6);
    data.put("frameContextTransitionP99Ms", transitions.p99Nanos() / 1e6);
    data.put("frameContextTransitionMaxMs", transitions.maxNanos() / 1e6);
    data.put("frameContextTransitionScope", "Observed crossing frame gaps including waits; not isolated world-load or GPU time");
    data.put("frameWindowGeneration", frames.generation());
    data.put("frameTimingScope", "CPU frame intervals including waits and limiting; not GPU time");
    data.put("frameWidth", mc.getWindow().getWidth());
    data.put("frameHeight", mc.getWindow().getHeight());
    data.put("frameMaxMs", stats.maxNanos() / 1e6);
    data.put("windowFocused", mc.isWindowActive());
    data.put("effectiveFpsLimit", mc.getFramerateLimitTracker().getFramerateLimit());
    data.put("entitiesSkipped", VisualPerformance.entitiesSkipped);
    data.put("blockEntitiesSkipped", VisualPerformance.blockEntitiesSkipped);
    data.put("particlesSkipped", VisualPerformance.particlesSkipped);
    data.put("fps", mc.getFps());
    data.put("rendererOwner", RendererOwnership.owner());
    data.put("graphicsApi", RenderSystem.getDevice().getBackendName());
    data.put("nativeSyncBuilds", VisualPerformance.chunkSyncBuilds);
    data.put("nativeRebuildsDeferred", VisualPerformance.chunkRebuildsDeferred);
    data.put("nativeRebuildsCoalesced", VisualPerformance.chunkRebuildsCoalesced);
    var water = com.shnewbs.deepprimal.client.render.AnimatedWaterRenderer.INSTANCE;
    data.put("waterGpuBytes", water.residentBytes);
    data.put("waterPatchUploads", water.uploads);
    data.put("waterPatchPending", water.pending());
    data.put("waterTerrainInvalidationsAvoided", water.terrainInvalidationsAvoided);
    data.put("nativePlayerBuilds", VisualPerformance.chunkPlayerBuilds);
    data.put("nativeSyncBuildMsPerSample", (VisualPerformance.chunkSyncNanos - lastSync) / 1e6);
    lastSync = VisualPerformance.chunkSyncNanos;
    data.put("gpu", RenderSystem.getDevice().getRenderer());
    data.put(
        "wakeMeshBytes",
        com.shnewbs.deepprimal.client.render.WakeRenderer.INSTANCE.residentBytes());
    data.put(
        "oceanMeshBytes",
        com.shnewbs.deepprimal.client.render.WaterSurfaceRenderer.INSTANCE.residentBytes());
    data.put(
        "oceanPendingSamples",
        com.shnewbs.deepprimal.client.render.WaterSurfaceRenderer.INSTANCE.pendingSamples());
    data.put("renderDistance", mc.options.renderDistance().get());
    data.put("effectiveRenderDistance", mc.options.getEffectiveRenderDistance());
    data.put("memoryDistanceGuard", com.shnewbs.deepprimal.performance.MemorySafety.enabled());
    data.put("simulationDistance", mc.options.simulationDistance().get());
    data.put(
        "verticalRadius",
        RendererOwnership.owned()
            ? ClientPerformanceConfig.VERTICAL_RENDER_DISTANCE.get()
            : "External");
    data.put("farDistance", RendererOwnership.owned() ? HorizonRenderer.farDistance() : 0);
    if (RendererOwnership.owned()) {
      var renderer = HorizonRenderer.INSTANCE;
      data.put("horizonResidentBytes", renderer.residentBytes);
      data.put("horizonTransitionBuilds", renderer.transitionBuilds);
      data.put("horizonWorkFraction", renderer.workFraction());
      data.put("horizonTargetFps", ClientPerformanceConfig.TARGET_FPS.get());
      data.put(
          "horizonMemoryLimitBytes", ClientPerformanceConfig.HORIZON_MEMORY_MIB.get() * 1048576L);
      data.put(
          "horizonBuildMsPerSample",
          (renderer.meshBuildNanos + renderer.meshPackNanos - lastBuild) / 1e6);
      lastBuild = renderer.meshBuildNanos + renderer.meshPackNanos;
      data.put("horizonUploadMsPerSample", (renderer.uploadNanos - lastUpload) / 1e6);
      lastUpload = renderer.uploadNanos;
      data.put("horizonDrawCpuMsPerSample", (renderer.drawCpuNanos - lastDraw) / 1e6);
      lastDraw = renderer.drawCpuNanos;
      data.put("horizonReceivedBytesPerSample", renderer.receivedBytes - lastReceived);
      lastReceived = renderer.receivedBytes;
      data.put("horizonGpuTimingAvailable", renderer.gpuTimingAvailable());
      data.put("horizonGpuMs", renderer.gpuMs());
      data.put("horizonCulledTiles", renderer.culledTiles);
      data.put("horizonBatchedSubmission", ClientPerformanceConfig.BATCHED_DRAWS.get());
      data.put("horizonBackgroundPaused", HorizonRenderer.backgroundWorkPaused());
      data.put("horizonUploadsLastFrame", renderer.uploadsLastFrame);
      data.put("horizonUploadBytesLastFrame", renderer.uploadBytesLastFrame);
      data.put("horizonMaxUploadsPerFrame", renderer.maxUploadsPerFrame);
      data.put("horizonMaxUploadBytesPerFrame", renderer.maxUploadBytesPerFrame);
      data.put("horizonFineVisible", renderer.visibleFine);
      data.put("horizonMediumVisible", renderer.visibleMedium);
      data.put("horizonCoarseVisible", renderer.visibleCoarse);
      data.put("horizonState", renderer.status);
      data.put("horizonCached", renderer.cachedTiles);
      data.put("horizonTarget", renderer.targetTiles);
      data.put("horizonVisible", renderer.visibleTiles);
      data.put("horizonBackgroundDepthBytes", renderer.backgroundDepthBytes());
      data.put("horizonTrianglesDrawn", renderer.drawnTriangles);
      data.put("horizonUploadedBytes", renderer.uploadedBytes);
    }
    data.putAll(com.shnewbs.deepprimal.settings.LodAccess.diagnostics());
    if (mc.level != null) data.put("dimension", mc.level.dimension().identifier().toString());
    LocalDashboard.client(data);
  }
}

package com.shnewbs.deepprimal.core;

import java.util.Random;

/** Dependency-free differential checks for hot-path math and bounded memory behavior. */
public final class CoreChecks {
  public static void main(String[] args) throws Exception {
    FrameIntervalChecks.main(args);
    AquiferTickChecks.main(args);
    EngineIntegrationTest.main(new String[0]);
    CacheLifecycleChecks.main(new String[0]);
    CoreCloseLifecycleChecks.main(new String[0]);
    PipelineInlineCloseChecks.main(new String[0]);
    ByteLruOverflowChecks.main(new String[0]);
    DensityGridFiniteChecks.main(new String[0]);

    com.shnewbs.deepprimal.core.lod.LodStoreBudgetChecks.main(new String[0]);
    com.shnewbs.deepprimal.core.lod.LodByteAccountingChecks.main(new String[0]);
    TerrainV6Checks.run();
    TerrainV7Checks.run();
    GradientPaletteChecks.run();
    SoilTextureChecks.run();
    com.shnewbs.deepprimal.core.density.NoiseCoreChecks.main(new String[0]);
    com.shnewbs.deepprimal.core.density.DensityGraphChecks.main(new String[0]);
    com.shnewbs.deepprimal.core.density.ReuseChecks.main(new String[0]);
    com.shnewbs.deepprimal.core.density.AdversarialChecks.main(new String[0]);
    com.shnewbs.deepprimal.core.density.DensityChunkChecks.run();
    WaterBedChecks.run();
    DepositPlanChecks.run();
    WaterBudgetChecks.run();
    SplitAdmissionChecks.main(args);
    StreamSourceCapacityChecks.run();
    BoatBuoyancyChecks.run();
    TerrainV4Checks.run();
    DepositFieldChecks.run();
    DepositAllocationChecks.run();
    WaterAnimationChecks.run();
    WaterFlowTextureChecks.run();
    WaterFlowBlendChecks.run();
    WaterFlowFieldChecks.run();
    WaterCornerPacketChecks.run();
    WaterCornerBulkChecks.run();
    WaterBoundaryIndexChecks.run();
    WaterCornerRetryChecks.run();
    WaterRetirementStateChecks.run();
    WaterSurfaceShapeChecks.run();
    WaterfallSideChecks.run();
    CaveColumnChecks.run();
    IntegratedEngineChecks.run();
    EngineAuditChecks.run();
    TerrainRevisionChecks.run();
    WatershedChecks.run();
    WaterwayChecks.run();
    DrainageChecks.run();
    RuntimeChecks.run();
    HorizonChecks.run();
    WaterDynamicsChecks.run();
    HydrologyChecks.run();
    check(
        RendererPolicy.ownsRenderer(java.util.Set.of("deepprimal", "lithium", "ferritecore")),
        "unrelated optimizers retain renderer");
    for (String id : RendererPolicy.REPLACEMENTS)
      check(
          !RendererPolicy.ownsRenderer(java.util.Set.of(id)), "replacement owns rendering: " + id);
    for (int x : new int[] {-58000, -1, 0, 1, 58000})
      for (int z : new int[] {-58000, -1, 0, 1, 58000}) {
        long key = FarTerrain.key(x, z);
        check(FarTerrain.x(key) == x && FarTerrain.z(key) == z, "signed tile key");
      }
    check(FarTerrain.inRange(-1, -1, 0, 0, 1), "negative tile touching view");
    check(!FarTerrain.inRange(9, 0, 0, 0, 256), "outside horizon");
    check(FarTerrain.inRange(7, 0, 0, 0, 256), "inside horizon");
    for (int capacity = 2; capacity <= DistancePolicy.MAX_RENDER; capacity++) {
      int buckets = DistancePolicy.queuePriorityCount(46, capacity);
      check(capacity + 2 < buckets, "tracker removal priority fits queue");
      check(buckets >= 46, "native generation queue bounds retained");
      if (capacity <= 43) check(buckets == 46, "ordinary views retain native allocation");
    }
    check(DistancePolicy.parse("0", 0, 96).orElseThrow() == 0, "full-height input");
    check(DistancePolicy.parse("1", 0, 96).orElseThrow() == 1, "minimum vertical radius");
    check(
        VerticalRange.fogScale(2, 64, 8) == 0.25f, "vertical fog extends beyond horizontal range");
    check(VerticalRange.fogScale(16, 64, 2) == 8.0f, "vertical fog closes within smaller radius");
    check(VerticalRange.fogScale(2, 64, 0) == 0.03125f, "full-height fog radius");
    for (String invalid : new String[] {"", "-1", "97", "1.0", "no", "1000"})
      check(DistancePolicy.parse(invalid, 0, 96).isEmpty(), "invalid vertical input");
    for (int worldMin : new int[] {-24, -8, 0})
      for (int worldSize : new int[] {24, 48, 64}) {
        for (int radius : new int[] {0, 1, 2, 8, 32, 96})
          for (int camera = worldMin - 4; camera <= worldMin + worldSize + 4; camera++) {
            int count = VerticalRange.count(worldSize, radius);
            int low = VerticalRange.low(camera, worldMin, worldSize, radius);
            boolean[] found = new boolean[count];
            for (int slot = 0; slot < count; slot++) {
              int y = VerticalRange.coordinate(low, count, slot);
              check(
                  y >= low && y < low + count && !found[y - low], "unique vertical ring coverage");
              check(Math.floorMod(y, count) == slot, "negative vertical lookup");
              found[y - low] = true;
            }
            check(
                low >= worldMin && low + count <= worldMin + worldSize,
                "window inside saved height");
          }
      }
    WorkBudget budget = new WorkBudget();
    for (int i = 0; i < 100; i++) budget.observe(50, 16.67, 0.5);
    check(budget.fraction() == 0.125, "work backoff floor");
    for (int i = 0; i < 59; i++) budget.observe(16, 16.67, 0.5);
    check(budget.fraction() == 0.125, "recovery hysteresis");
    budget.observe(16, 16.67, 0.5);
    check(budget.fraction() > 0.125, "gradual recovery");
    for (int i = 0; i < 10000; i++) budget.observe(16, 16.67, 0.5);
    check(budget.fraction() == 1, "recovery ceiling");
    budget.observe(1, 16.67, 0.9);
    check(budget.fraction() < 1, "heap pressure backoff");
    Random random = new Random(20261018L);
    int checked = 0;
    for (int lower : new int[] {-384, -128}) {
      for (int i = 0; i < 100_000; i++) {
        // Quarter-block heights exercise negative coordinates and exact cell boundaries.
        double h = (random.nextInt(6000) - 2000) / 4.0;
        int expected = lower;
        for (int y = 632; y >= lower; y -= 8)
          if (h > y) {
            expected = y;
            break;
          }
        int actual = ColumnHeight.surfaceY(h, lower, 632, 8);
        if (actual != expected) throw new AssertionError(h + ": " + actual + " != " + expected);
        checked++;
      }
    }
    BoundedLru<Integer, Integer> cache = new BoundedLru<>(3);
    cache.put(1, 1);
    cache.put(2, 2);
    cache.put(3, 3);
    check(cache.get(1) == 1, "cache hit");
    cache.put(4, 4);
    check(cache.get(2) == null && cache.size() == 3, "LRU eviction");
    for (int i = 0; i < 100_000; i++) cache.put(i, i);
    check(cache.size() == 3, "cache capacity under stress");
    cache.clear();
    check(cache.size() == 0 && cache.hits() == 0, "reload reset");
    BoundedLru<Integer, Integer> disabled = new BoundedLru<>(0);
    disabled.put(1, 1);
    check(disabled.size() == 0, "disabled cache");
    TickWindow ticks = new TickWindow(3);
    ticks.record(1_000_000);
    ticks.record(2_000_000);
    ticks.record(3_000_000);
    ticks.record(4_000_000);
    check(ticks.count() == 3 && ticks.snapshot().medianMs() == 3, "tick ring rollover");
    ticks.clear();
    check(ticks.snapshot().count() == 0, "tick reset");
    System.out.println(
        "PASS: "
            + checked
            + " differential surface cases, bounded-cache stress, tick-ring rollover.");
  }

  private static void check(boolean value, String message) {
    if (!value) throw new AssertionError(message);
  }
}

package com.shnewbs.deepprimal.core;

import java.util.ArrayDeque;
import java.util.Random;

public final class FrameIntervalChecks {
  public static void main(String[] args) {
    TransitionIntervalChecks.main(args);
    Object world = new Object();
    var window = new FrameIntervalWindow(512);
    long now = 0;
    if (!observe(window, now, world, 1920, 1080, true, 120, 32, 16, 192)
        || window.snapshot().samples() != 0) throw new AssertionError("First timestamp zero");
    var oracle = new ArrayDeque<Long>();
    var random = new Random(20261027);
    int checks = 0;
    for (int i = 0; i < 10000; i++) {
      long interval = random.nextInt(100000001);
      now += interval;
      if (observe(window, now, world, 1920, 1080, true, 120, 32, 16, 192))
        throw new AssertionError("Stable context reset");
      oracle.addLast(interval);
      if (oracle.size() > 512) oracle.removeFirst();
      if (i % 13 != 0) continue;
      long[] sorted = oracle.stream().mapToLong(Long::longValue).sorted().toArray();
      var s = window.snapshot();
      if (s.samples() != sorted.length || s.p50Nanos() != percentile(sorted, 50)
          || s.p95Nanos() != percentile(sorted, 95) || s.p99Nanos() != percentile(sorted, 99)
          || s.maxNanos() != sorted[sorted.length - 1]) throw new AssertionError("Oracle");
      checks++;
    }
    // Each independent context coordinate changes while the others stay fixed.
    int resets = 0;
    for (int field = 0; field < 8; field++) {
      window.clear();
      observe(window, 100, world, 1920, 1080, true, 120, 32, 16, 192);
      observe(window, 110, world, 1920, 1080, true, 120, 32, 16, 192);
      long before = window.generation();
      Object nextWorld = field == 0 ? new Object() : world;
      int w = field == 1 ? 1280 : 1920, h = field == 2 ? 720 : 1080;
      boolean f = field != 3;
      int fps = field == 4 ? 60 : 120, full = field == 5 ? 16 : 32;
      int vertical = field == 6 ? 8 : 16, lod = field == 7 ? 256 : 192;
      if (!observe(window, 1000000000, nextWorld, w, h, f, fps, full, vertical, lod)
          || window.generation() != before + 1 || window.snapshot().samples() != 0)
        throw new AssertionError("Crossing interval " + field);
      if (observe(window, 1000000007, nextWorld, w, h, f, fps, full, vertical, lod)
          || window.snapshot().p99Nanos() != 7) throw new AssertionError("Next interval");
      resets++;
    }
    window.clear();
    observe(window, Long.MAX_VALUE - 2, null, 0, 0, false, 0, 0, 0, 0);
    if (observe(window, Long.MIN_VALUE + 2, null, 0, 0, false, 0, 0, 0, 0)
        || window.snapshot().p99Nanos() != 5) throw new AssertionError("nanoTime wrap");
    if (!observe(window, Long.MIN_VALUE, null, 0, 0, false, 0, 0, 0, 0)
        || window.snapshot().samples() != 0) throw new AssertionError("Clock reversal");
    window.clear();
    if (!observe(window, 999, world, 1920, 1080, true, 120, 32, 16, 192)
        || window.snapshot().samples() != 0) throw new AssertionError("Observation gap");
    System.out.println("FRAME_INTERVAL_PASS oracleWindows=" + checks
        + " intervals=10000 bounded=512 independentContextResets=" + resets
        + " zeroOrigin=true clockWrap=true clockReversal=true observationGap=true");
  }

  private static boolean observe(FrameIntervalWindow w, long now, Object world, int width,
      int height, boolean focused, int fps, int full, int vertical, int lod) {
    return w.observe(now, world, width, height, focused, fps, full, vertical, lod);
  }
  private static long percentile(long[] sorted, int p) {
    return sorted[(int) Math.ceil(sorted.length * p / 100.0) - 1];
  }
}

package com.shnewbs.deepprimal.core;

import java.util.ArrayDeque;

public final class TransitionIntervalChecks {
  public static void main(String[] args) {
    int checks = 0;
    for (int capacity : new int[] {1, 17, 64, 512}) {
      var window = new FrameIntervalWindow(capacity);
      Object world = new Object();
      long now = 0;
      observe(window, now, world);
      if (window.transitionSnapshot().samples() != 0 || window.transitionCount() != 0)
        throw new AssertionError("Invented first transition");
      var oracle = new ArrayDeque<Long>();
      for (int i = 0; i < 256; i++) {
        now += 7;
        observe(window, now, world);
        if (window.snapshot().p99Nanos() != 7) throw new AssertionError("Steady interval");
        long gap = 1000000L + i * 7919L;
        now += gap;
        world = new Object();
        observe(window, now, world);
        oracle.addLast(gap);
        if (oracle.size() > Math.min(capacity, 64)) oracle.removeFirst();
        long[] sorted = oracle.stream().mapToLong(Long::longValue).sorted().toArray();
        var s = window.transitionSnapshot();
        if (window.transitionCount() != i + 1 || s.samples() != sorted.length
            || s.p50Nanos() != percentile(sorted, 50) || s.p95Nanos() != percentile(sorted, 95)
            || s.p99Nanos() != percentile(sorted, 99) || s.maxNanos() != sorted[sorted.length - 1]
            || window.snapshot().samples() != 0) throw new AssertionError("Transition oracle");
        checks++;
      }
      var retained = window.transitionSnapshot();
      now += 7; observe(window, now, world);
      if (!retained.equals(window.transitionSnapshot()) || window.snapshot().p99Nanos() != 7)
        throw new AssertionError("Steady sample polluted transition window");
      observe(window, now - 1, new Object());
      if (!retained.equals(window.transitionSnapshot()) || window.transitionCount() != 256)
        throw new AssertionError("Negative gap admitted");
      window.clear();
      if (window.transitionCount() != 0 || window.transitionSnapshot().samples() != 0)
        throw new AssertionError("Clear retained history");
      observe(window, Long.MAX_VALUE - 2, null);
      observe(window, Long.MIN_VALUE + 2, new Object());
      if (window.transitionCount() != 1 || window.transitionSnapshot().p99Nanos() != 5)
        throw new AssertionError("Crossing clock wrap");
      window.clear();
      observe(window, 100, null); observe(window, 100, new Object());
      if (window.transitionCount() != 1 || window.transitionSnapshot().p99Nanos() != 0)
        throw new AssertionError("Zero gap omitted");
    }
    System.out.println("TRANSITION_INTERVAL_PASS oracleWindows=" + checks
        + " capacities=1,17,64,512 crossingBound=64 noSteadyPollution=true"
        + " clear=true negativeRejected=true wrap=true zero=true");
  }

  private static void observe(FrameIntervalWindow window, long now, Object world) {
    window.observe(now, world, 1920, 1080, true, 120, 32, 16, 192);
  }
  private static long percentile(long[] values, int p) {
    return values[(int) Math.ceil(values.length * p / 100.0) - 1];
  }
}
